const fs = require('fs');
const body = $('Webhook Start').first().json.body || {};
const execId = $execution.id;
const stage1 = $('Workflow Config').first().json.cre_acq_stage1;
const dealId = body.deal_id || String(execId);
const config = {
  mode: 'stop-before-scoring',
  folder: body.deal_folder,
  deal_id: dealId,
  run_id: String(execId),
  tmp_dir: '/tmp'
};
const path = '/tmp/om-screener-' + execId + '.json';
fs.writeFileSync(path, JSON.stringify(config));
return [{ json: { configPath: path } }];

const fs = require('fs');
const resume = $input.first().json;
const body = resume.body || resume;
let corrections = body.corrections;
if (corrections === undefined || corrections === null) {
  corrections = '';
} else if (typeof corrections === 'object') {
  corrections = JSON.stringify(corrections);
} else {
  corrections = String(corrections);
}
if (!corrections) {
  throw new Error('Missing corrections in resume payload');
}
const execId = $execution.id;
const stage1 = $('Workflow Config').first().json.cre_acq_stage1;
const dealId = ($('Webhook Start').first().json.body || {}).deal_id || String(execId);
const config = {
  mode: 'confirm-only',
  deal_id: dealId,
  corrections: corrections,
  run_id: String(execId),
  tmp_dir: '/tmp',
  stage_dir: stage1
};
const path = '/tmp/om-screener-resume-' + execId + '.json';
fs.writeFileSync(path, JSON.stringify(config));
return [{ json: { configPath: path } }];
